export function getLesson7SourceItem(id: string): Lesson7LedgerItem {
  const item = LESSON7_LEDGER.find((entry) => entry.id === id)
  if (!item) throw new Error(`Unknown lesson 7 source item: ${id}`)
  return item
}

/** Exact printed wording; mathematical presentation is mapped separately to KaTeX. */
export function lesson7SourceText(id: string): string {
  return getLesson7SourceItem(id).content
}

