export type Lesson7LedgerCoverage = {
  total: number
  implemented: number
  sourceImage: number
  deferred: string[]
  byPage: Record<string, number>
  danglingSteps: string[]
  danglingQuestions: string[]
  unlistedTextbookQuestions: string[]
  pagesWithoutEntries: string[]
}

function allQuestions(lesson: LessonDefinition) {
  const result: NonNullable<LessonDefinition['tests']>[number]['questions'] = []
  const walk = (questions: typeof result) => {
    for (const question of questions) {
      result.push(question)
      if (question.type === 'table-interpretation' || question.type === 'diagram-interpretation') walk(question.questions)
    }
  }
  for (const test of lesson.tests ?? []) walk(test.questions)
  return result
}

export function computeLedgerCoverage(lesson: LessonDefinition): Lesson7LedgerCoverage {
  const stepIds = new Set(lesson.steps.map((step) => step.id))
  const questions = allQuestions(lesson)
  const questionIds = new Set(questions.map((question) => question.id))
  const listed = new Set(LESSON7_LEDGER.flatMap((item) => item.questionIds))
  const byPage: Record<string, number> = {}
  for (const item of LESSON7_LEDGER) byPage[item.page] = (byPage[item.page] ?? 0) + 1
  return {
    total: LESSON7_LEDGER.length,
    implemented: LESSON7_LEDGER.filter((item) => item.status === 'implemented').length,
    sourceImage: LESSON7_LEDGER.filter((item) => item.status === 'source-image').length,
    deferred: LESSON7_LEDGER.filter((item) => item.status === 'deferred').map((item) => item.id),
    byPage,
    danglingSteps: LESSON7_LEDGER.flatMap((item) => item.implementedBy.filter((id) => !stepIds.has(id))),
    danglingQuestions: LESSON7_LEDGER.flatMap((item) => item.questionIds.filter((id) => !questionIds.has(id))),
    unlistedTextbookQuestions: questions.filter((q) => q.origin === 'textbook' && !listed.has(q.id)).map((q) => q.id),
    pagesWithoutEntries: lesson.source.pages.map((page) => page.page).filter((page) => !byPage[page]),
  }
}

export function stepBlocks(lesson: LessonDefinition, stepId: string): ContentBlock[] {
  return lesson.steps.find((step) => step.id === stepId)?.blocks ?? []
}
